import{_ as o,C as s,o as n,c as i,j as a,a as t,E as l,a3 as d}from"./chunks/framework.CZBGEXos.js";const w=JSON.parse('{"title":"Spreads","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/spreads.md","filePath":"en/tools/spreads.md"}'),h={name:"en/tools/spreads.md"};function c(p,e,u,m,g,f){const r=s("Screenshot");return n(),i("div",null,[e[0]||(e[0]=a("h1",{id:"spreads",tabindex:"-1"},[t("Spreads "),a("a",{class:"header-anchor",href:"#spreads","aria-label":'Permalink to "Spreads"'},"​")],-1)),e[1]||(e[1]=a("p",null,[t("Spreads shows the "),a("strong",null,"same coin priced differently on different exchanges"),t(" right now: how wide the gap is, how long it has been open, and the volume and funding behind every price.")],-1)),l(r,{src:"web-spreads",alt:"The Spreads tool in the web app with several spread cards",caption:"Spreads in the web app — a new-listing pop-up in the corner"}),e[2]||(e[2]=d('<div class="info custom-block"><p class="custom-block-title">Formerly Alerts</p><p>Until October 2026 this tool was called <strong>Alerts</strong> and also showed new listings and liquidations. Listings are now <a href="/manual/en/getting-started.html#new-listing-pop-ups">pop-ups</a> in every tool, and liquidations moved to <a href="/manual/en/tools/ticks.html#liquidations">Ticks</a>.</p></div><h2 id="reading-the-window" tabindex="-1">Reading the window <a class="header-anchor" href="#reading-the-window" aria-label="Permalink to &quot;Reading the window&quot;">​</a></h2><h3 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h3><p>The toolbar shows the settings in force. In the web app each chip is a quick filter you can click to change in place:</p><ul><li><strong>Timeframe</strong> — the candle interval of the cards&#39; charts, e.g. <code>1m chart</code>.</li><li><strong>Spread ≥ …</strong> — the <a href="#minimum-spread">minimum spread</a>.</li><li><strong>Max age</strong> — <a href="#max-spread-age">max spread age</a>; <code>Any age</code> when off.</li><li><strong>Max width</strong> — <a href="#max-spread">max spread %</a>; <code>Any width</code> when off.</li><li><strong>Volume</strong> — the <a href="#volume-filter">volume filter</a>; <code>Any volume</code> when off.</li><li><strong>Sort</strong> — the order of the cards: <strong>Newest</strong>, <strong>Spread</strong>, <strong>Age</strong> or <strong>Volume</strong>.</li></ul><h3 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to &quot;Order&quot;">​</a></h3><p>By default cards are ordered newest first, by <strong>when the spread opened</strong>. A card keeps its position as its numbers update, so the feed does not reshuffle under you while you&#39;re reading it. In the web app you can sort by the widest spread, the longest open, or the highest combined volume instead.</p><h3 id="a-spread-card" tabindex="-1">A spread card <a class="header-anchor" href="#a-spread-card" aria-label="Permalink to &quot;A spread card&quot;">​</a></h3><ul><li><p><strong>Symbol</strong> — click to copy it to your clipboard.</p></li><li><p><strong>Age</strong> — how long the spread has been at or above your threshold, e.g. <code>12m</code> or <code>3h</code>.</p></li><li><p><strong>Spread</strong> — the live maximum price spread across exchanges, as a percentage.</p></li><li><p><strong>Exchange rows</strong> — one row per exchange that lists the coin, with a colored dot matching its line on the chart:</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td>Exchange</td><td>Where the price comes from</td></tr><tr><td>24h vol</td><td>That exchange&#39;s 24-hour volume. The shaded bar shows its share of the coin&#39;s total volume across these exchanges</td></tr><tr><td>Funding</td><td>The current funding rate there — green when longs pay, red when shorts pay</td></tr><tr><td>Next</td><td>Time until that exchange&#39;s next funding payment</td></tr></tbody></table></li><li><p><strong>Chart</strong> — one price line per exchange, so you can see whether the gap is opening, closing, or holding.</p></li><li><p><strong>Fullscreen</strong> — the expand button opens the card full size; see <a href="#fullscreen">Fullscreen</a>.</p></li></ul><h4 id="dimmed-cards" tabindex="-1">Dimmed cards <a class="header-anchor" href="#dimmed-cards" aria-label="Permalink to &quot;Dimmed cards&quot;">​</a></h4><p>A card turns <strong>dimmed</strong> when its live spread drops back below your <a href="#minimum-spread">minimum spread</a>. The spread is not over yet — the server keeps it open until it has stayed below the threshold for <strong>10 minutes</strong>. If it widens again, the card lights back up and keeps its age. If not, it drops out of the feed.</p><p>The sound plays once per new spread, not again when a dimmed card comes back.</p><h4 id="how-the-spread-is-calculated" tabindex="-1">How the spread is calculated <a class="header-anchor" href="#how-the-spread-is-calculated" aria-label="Permalink to &quot;How the spread is calculated&quot;">​</a></h4><p>The percentage is <code>(highest price − lowest price) ÷ lowest price × 100</code>, taken across every exchange currently reporting that coin.</p><p>This figure is <strong>live</strong>. It is recomputed continuously from the same exchange streams that feed the chart lines, so it tracks the current gap rather than the gap at the moment the spread opened.</p><p>Two kinds of price are left out, because neither is a gap anyone can trade:</p><ul><li><strong>A frozen price.</strong> An exchange that has gone a whole 5-minute candle without a single trade on the coin is dropped from its spread — a delisted contract in settlement keeps streaming its last price for hours.</li><li><strong>A different asset under the same name.</strong> A price more than twice, or less than half, the middle price across exchanges is treated as another coin with the same ticker (for example a stock perp and a crypto token both called <code>BB</code>) and left out. If only two exchanges remain and they disagree that much, the coin is not shown at all.</li></ul><div class="warning custom-block"><p class="custom-block-title">A spread is not a guaranteed profit</p><p>The number is a difference between two quoted prices. It says nothing about whether you could actually trade it — order book depth, fees, funding, transfer time and withdrawal availability are not part of the calculation, and a visible gap can close before an order fills. Treat it as a signal to look, not a result.</p></div><p>The chart is deliberately zoomed in with tight price margins, because the gap between exchange lines is usually small relative to the price and would be invisible at a normal scale.</p><h3 id="fullscreen" tabindex="-1">Fullscreen <a class="header-anchor" href="#fullscreen" aria-label="Permalink to &quot;Fullscreen&quot;">​</a></h3><p>The expand button opens a card at full size: the same price lines per exchange, the exchange rows with volume and funding, the live spread and its age. Pick the timeframe at the top. In the web app the fullscreen chart also has the <a href="/manual/en/getting-started.html#drawing-in-fullscreen">drawing tools</a>; drawings here are kept per coin, separately from the other tools. Press <kbd>Esc</kbd> or the close button to exit.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Open Spreads&#39; settings: the icon at the right of the toolbar (web), or the <strong>Spreads</strong> tab in the main window (Windows).</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>How many cards the feed shows at once. Range <strong>3 to 50</strong>, default 9.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>The candle interval used for the price lines inside the cards. Options: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>. Default <code>1m</code>.</p><p>This only changes the chart. It does not change how the spread is calculated or which spreads qualify.</p><h3 id="spread-settings" tabindex="-1">Spread settings <a class="header-anchor" href="#spread-settings" aria-label="Permalink to &quot;Spread settings&quot;">​</a></h3><h4 id="minimum-spread" tabindex="-1">Minimum spread <a class="header-anchor" href="#minimum-spread" aria-label="Permalink to &quot;Minimum spread&quot;">​</a></h4><p>The spread a coin must reach before it shows up. Range <strong>1% to 10%</strong> in 0.5% steps, default 1%.</p><p>A spread that falls back below this value is <a href="#dimmed-cards">dimmed</a>, not removed at once. It leaves the feed after 10 minutes below the threshold.</p><h4 id="max-spread" tabindex="-1">Max spread % <a class="header-anchor" href="#max-spread" aria-label="Permalink to &quot;Max spread %&quot;">​</a></h4><p>Hides spreads wider than this. Default <strong>off</strong> (empty). The − / + buttons step by 5%, or type any value.</p><p>A spread of hundreds of percent is almost never a real opportunity. The server already leaves out <a href="#how-the-spread-is-calculated">different assets with the same name</a>, but a cap still helps with the rest. <strong>50%</strong> is a good starting point.</p><h4 id="max-spread-age" tabindex="-1">Max spread age <a class="header-anchor" href="#max-spread-age" aria-label="Permalink to &quot;Max spread age&quot;">​</a></h4><p>Hides spreads that have been open longer than this. Steps: <strong>Off</strong>, 30m, 1h, 2h, 4h, 8h, 12h, 1d, 2d, 3d, 7d. Default Off.</p><p>A gap that has stayed open for days is usually structural — a suspended withdrawal, a different token — rather than something that will close.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="new-spread-sound" tabindex="-1">New spread sound <a class="header-anchor" href="#new-spread-sound" aria-label="Permalink to &quot;New spread sound&quot;">​</a></h4><p>Plays a sound when a new spread opens. On by default.</p><h3 id="volume-filter" tabindex="-1">Volume filter <a class="header-anchor" href="#volume-filter" aria-label="Permalink to &quot;Volume filter&quot;">​</a></h3><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Filters spreads by 24-hour trading volume. Off by default.</p><div class="info custom-block"><p class="custom-block-title">It takes two</p><p>A spread needs <strong>at least two exchanges</strong> above the minimum volume to pass the filter. That is deliberate: a price gap is only meaningful if both sides of it have real trading behind them.</p></div><h4 id="minimum-24h-volume" tabindex="-1">Minimum 24h volume <a class="header-anchor" href="#minimum-24h-volume" aria-label="Permalink to &quot;Minimum 24h volume&quot;">​</a></h4><p>The 24-hour volume, in USD, an exchange needs for its side of a spread to count. Type the amount; default <strong>$1,000,000</strong>.</p><p>Greyed out unless the volume filter is enabled.</p><div class="info custom-block"><p class="custom-block-title">All of these filters run on the server</p><p>Minimum spread, max spread %, max age and the volume filter are all applied on the server, so a hidden spread never reaches the app at all. Changing a value takes effect within a second.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/manual/en/tools/knives.html">Knives</a> — single-exchange price moves rather than cross-exchange gaps</li><li><a href="/manual/en/tools/monitor.html">Monitor</a> — ranked market overview</li><li><a href="/manual/en/getting-started.html#new-listing-pop-ups">New-listing pop-ups</a> — formerly part of this tool</li></ul>',52))])}const x=o(h,[["render",c]]);export{w as __pageData,x as default};
